#!/bin/sh
# Answers Claude Code's PreToolUse hook for every Subscriby tool the catalogue
# flags destructive: ask the user before it runs, whatever the session's
# permission settings. hooks.json (generated by npm run sync) names this file
# and carries the tool list in its matcher; the file reads nothing from the
# call and changes no argument. A shell file rather than a node one, because
# Claude Code runs without Node on a native install and requires Git Bash on
# Windows, so sh is the one interpreter every install has.
printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"This Subscriby tool changes or removes existing data. Confirm it before it runs."}}'
